import Model from 'flarum/common/Model';
export default class Suggestion extends Model {
  status = (() => Model.attribute('status'))();
  endorsementCount = (() => Model.attribute('endorsementCount'))();
  createdAt = (() => Model.attribute('createdAt', Model.transformDate))();
  user = (() => Model.hasOne('user'))();
  tag = (() => Model.hasOne('tag'))();
}
flarum.reg.add('ramon-tag-experts', 'common/models/Suggestion', Suggestion);