import app from 'flarum/common/app';
import Component from 'flarum/common/Component';
import Avatar from 'flarum/common/components/Avatar';
import Button from 'flarum/common/components/Button';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import Select from 'flarum/common/components/Select';
import username from 'flarum/common/helpers/username';
import tagLabel from 'ext:flarum/tags/common/helpers/tagLabel';
import { expertGroupIds, t, tText } from '../utils/experts';

/**
 * A fila de sugestões de especialistas: quem recebeu endossos suficientes
 * numa tag. A mesma lista serve ao admin e à página da moderação no fórum.
 */
export default class SuggestionList extends Component {
  suggestions = [];
  loading = true;
  moreResults = false;
  busy = {};
  chosenGroup = {};
  oninit(vnode) {
    super.oninit(vnode);
    this.load();
  }
  view() {
    if (this.loading && !this.suggestions.length) {
      return m(LoadingIndicator, null);
    }
    if (!this.suggestions.length) {
      return m("p", {
        className: "TagExpertSuggestions-empty"
      }, t('lib.suggestions.empty'));
    }
    return m("div", {
      className: "TagExpertSuggestions"
    }, m("ul", {
      className: "TagExpertSuggestions-list"
    }, this.suggestions.map(suggestion => this.item(suggestion))), this.moreResults && m(Button, {
      className: "Button",
      loading: this.loading,
      onclick: () => this.load(this.suggestions.length)
    }, t('lib.suggestions.load_more')));
  }
  item(suggestion) {
    const user = suggestion.user() || null;
    const tag = suggestion.tag();
    const id = suggestion.id();
    const groups = tag ? this.groupsFor(tag) : [];
    const name = user ? tText('lib.suggestions.group_label', {
      username: user.displayName()
    }) : '';
    return m("li", {
      className: "TagExpertSuggestion",
      key: id
    }, m("div", {
      className: "TagExpertSuggestion-user"
    }, m(Avatar, {
      user: user
    }), m("div", {
      className: "TagExpertSuggestion-info"
    }, m("a", {
      className: "TagExpertSuggestion-name",
      href: user ? this.userUrl(user.slug()) : undefined,
      target: "_blank",
      rel: "noopener"
    }, username(user)), m("span", {
      className: "TagExpertSuggestion-meta"
    }, tag ? t('lib.suggestions.in_tag', {
      tag: tagLabel(tag)
    }) : null, ' · ', t('lib.suggestions.endorsements', {
      count: suggestion.endorsementCount()
    })))), m("div", {
      className: "TagExpertSuggestion-actions"
    }, groups.length > 1 && m(Select, {
      className: "TagExpertSuggestion-group",
      "aria-label": name,
      value: this.chosenGroup[id] || groups[0].id(),
      options: Object.fromEntries(groups.map(group => [group.id(), group.namePlural()])),
      onchange: value => this.chosenGroup[id] = value
    }), m(Button, {
      className: "Button Button--primary",
      icon: "fas fa-check",
      loading: this.busy[id],
      disabled: !groups.length,
      title: !groups.length ? tText('lib.suggestions.no_group') : undefined,
      onclick: () => this.resolve(suggestion, 'approved', groups)
    }, t('lib.suggestions.approve')), m(Button, {
      className: "Button",
      icon: "fas fa-times",
      disabled: this.busy[id],
      onclick: () => this.resolve(suggestion, 'dismissed', groups)
    }, t('lib.suggestions.dismiss'))));
  }
  groupsFor(tag) {
    return expertGroupIds(tag).map(id => app.store.getById('groups', id)).filter(group => !!group);
  }

  /** O admin não tem as rotas do fórum: o endereço do perfil sai da baseUrl. */
  userUrl(slug) {
    return `${app.forum.attribute('baseUrl')}/u/${encodeURIComponent(slug)}`;
  }
  async load(offset) {
    if (offset === void 0) {
      offset = 0;
    }
    this.loading = true;
    m.redraw();
    try {
      const results = await app.store.find('tag-expert-suggestions', {
        include: 'user.groups,tag',
        page: {
          offset
        }
      });
      this.suggestions = offset ? [...this.suggestions, ...results] : results;
      this.moreResults = !!results.payload?.links?.next;
    } finally {
      this.loading = false;
      m.redraw();
    }
  }
  async resolve(suggestion, status, groups) {
    const id = suggestion.id();
    const user = suggestion.user();
    const tag = suggestion.tag();
    const groupId = this.chosenGroup[id] || groups[0]?.id();
    this.busy[id] = true;
    try {
      await suggestion.save({
        status
      }, status === 'approved' ? {
        meta: {
          groupId: Number(groupId)
        }
      } : {});
      this.suggestions = this.suggestions.filter(item => item !== suggestion);
      app.alerts.show({
        type: 'success'
      }, status === 'approved' ? t('lib.suggestions.approved', {
        username: user ? user.displayName() : '',
        tag: tag ? tag.name() : ''
      }) : t('lib.suggestions.dismissed'));
    } finally {
      this.busy[id] = false;
      m.redraw();
    }
  }
}
flarum.reg.add('ramon-tag-experts', 'common/components/SuggestionList', SuggestionList);