import app from 'flarum/forum/app';
import Notification from 'flarum/forum/components/Notification';
import { t } from '../../common/utils/experts';

/** "Agora você é especialista em X", levando à tag. */
export default class BecameExpertNotification extends Notification {
  icon() {
    return 'fas fa-user-graduate';
  }
  href() {
    const tag = this.attrs.notification.subject();
    return tag ? app.route('tag', {
      tags: tag.slug()
    }) : app.route('index');
  }
  content() {
    const tag = this.attrs.notification.subject();
    return t('forum.notifications.approved_text', {
      tag: tag?.name() ?? ''
    });
  }
  excerpt() {
    return null;
  }
}
flarum.reg.add('ramon-tag-experts', 'forum/components/BecameExpertNotification', BecameExpertNotification);